def normalizar_ruts(apps, schema_editor):
    """Deja los RUT existentes sin puntos ni guion; si dos coinciden al normalizar, se dejan como estaban."""
    Cliente = apps.get_model("Inventario", "Cliente")
    grupos = {}
    for cliente in Cliente.objects.exclude(rut=""):
        normalizado = cliente.rut.replace(".", "").replace("-", "").replace(" ", "").upper()
        grupos.setdefault((cliente.negocio_id, normalizado), []).append(cliente)
    for (_, normalizado), clientes in grupos.items():
        if len(clientes) == 1 and clientes[0].rut != normalizado:
            clientes[0].rut = normalizado
            clientes[0].save(update_fields=["rut"])


